/**
 * Writes the data migration that seeds service categories, industry templates and plans from
 * `config/`. Run: node scripts/generate-templates-sql.ts
 * Re-running rewrites the same file; the SQL is idempotent (upserts).
 */
import { writeFileSync } from "node:fs";
import { INDUSTRY_TEMPLATES } from "../config/industry-templates.ts";
import { PLANS } from "../config/plans.ts";

const q = (s: string) => `'${s.replaceAll("'", "''")}'`;
const json = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  "-- Generated by scripts/generate-templates-sql.ts from config/. Do not edit by hand.",
  "",
];

INDUSTRY_TEMPLATES.forEach((t, i) => {
  lines.push(
    `insert into public.service_categories (code, name, sort) values (${q(t.code)}, ${q(t.name)}, ${i})`,
    `  on conflict (code) do update set name = excluded.name, sort = excluded.sort;`,
    `insert into public.industry_templates (code, version, name, definition, published) values (${q(t.code)}, ${t.version}, ${q(t.name)}, ${json(t)}, true)`,
    `  on conflict (code, version) do update set name = excluded.name, definition = excluded.definition, published = true;`,
  );
});

lines.push("");
PLANS.forEach((p, i) => {
  lines.push(
    `insert into public.plans (code, name, monthly_price_minor, setup_fee_minor, currency, positioning, illustrative, sort) values (${q(p.code)}, ${q(p.name)}, ${p.monthlyPriceMinor}, ${p.setupFeeMinor}, ${q(p.currency)}, ${q(p.positioning)}, true, ${i})`,
    `  on conflict (code) do update set name = excluded.name, monthly_price_minor = excluded.monthly_price_minor, setup_fee_minor = excluded.setup_fee_minor, positioning = excluded.positioning, sort = excluded.sort;`,
  );
  for (const [key, limit] of Object.entries(p.entitlements)) {
    lines.push(
      `insert into public.plan_entitlements (plan_code, key, limit_value) values (${q(p.code)}, ${q(key)}, ${limit === null ? "null" : limit})`,
      `  on conflict (plan_code, key) do update set limit_value = excluded.limit_value;`,
    );
  }
});

const out = new URL("../supabase/migrations/20261113000900_seed_templates_and_plans.sql", import.meta.url);
writeFileSync(out, lines.join("\n") + "\n");
console.log("wrote", out.pathname);
